"""POSIX-style word splitting with quoting and no expansions. See task.md."""

from __future__ import annotations


class SplitError(ValueError):
    """Raised for an unterminated quote or a lone trailing backslash."""


def split(line: str) -> list[str]:
    """Split `line` into words. See task.md for the rules."""
    words = []
    current_word = []
    i = 0
    in_single_quote = False
    in_double_quote = False
    word_open = False

    while i < len(line):
        ch = line[i]

        if in_single_quote:
            if ch == "'":
                in_single_quote = False
                i += 1
            else:
                current_word.append(ch)
                i += 1
        elif in_double_quote:
            if ch == '"':
                in_double_quote = False
                i += 1
            elif ch == "\\" and i + 1 < len(line):
                next_ch = line[i + 1]
                if next_ch in ("$", "`", '"', "\\"):
                    current_word.append(next_ch)
                    i += 2
                elif next_ch == "\n":
                    i += 2  # skip both backslash and newline
                else:
                    current_word.append(ch)
                    i += 1
            else:
                current_word.append(ch)
                i += 1
        else:
            if ch == "'":
                word_open = True
                in_single_quote = True
                i += 1
            elif ch == '"':
                word_open = True
                in_double_quote = True
                i += 1
            elif ch == "\\":
                if i + 1 < len(line):
                    next_ch = line[i + 1]
                    if next_ch == "\n":
                        i += 2  # line continuation
                    else:
                        word_open = True
                        current_word.append(next_ch)
                        i += 2
                else:
                    raise SplitError("trailing backslash")
            elif ch == "#" and not word_open:
                break  # comment
            elif ch in (" ", "\t"):
                if word_open:
                    words.append("".join(current_word))
                    current_word = []
                    word_open = False
                i += 1
            else:
                word_open = True
                current_word.append(ch)
                i += 1

    if in_single_quote or in_double_quote:
        raise SplitError("unterminated quote")

    if word_open:
        words.append("".join(current_word))

    return words
